      '세액공제 한도는 연금저축 단독으로는 연 600만원, IRP를 더하면 합산 연 900만원까지입니다. 공제율은 총급여 5,500만원(종합소득 4,500만원) 이하면 16.5%, 초과하면 13.2%가 적용됩니다. 즉 900만원을 채우면 소득 구간에 따라 연 118.8만~148.5만원을 세금에서 직접 돌려받는 셈입니다.',
